from typing import List


def kth_smallest_amount(coins: List[int], k: int) -> int:
    """Find the k-th value in the union of the denominations' positive multiples."""
    # Multiples of a denomination already covered by a smaller denomination add
    # nothing to the union.
    useful: list[int] = []
    for coin in sorted(coins):
        if not any(coin % smaller == 0 for smaller in useful):
            useful.append(coin)

    # Inclusion-exclusion coefficients, grouped by subset LCM.
    upper = min(coins) * k
    coefficients: dict[int, int] = {}
    for coin in useful:
        additions: dict[int, int] = {coin: 1} if coin <= upper else {}
        for multiple, coefficient in coefficients.items():
            lcm = multiple // gcd(multiple, coin) * coin
            if lcm <= upper:
                additions[lcm] = additions.get(lcm, 0) - coefficient
        for multiple, coefficient in additions.items():
            coefficients[multiple] = coefficients.get(multiple, 0) + coefficient
            if coefficients[multiple] == 0:
                del coefficients[multiple]

    def count_at_most(value: int) -> int:
        return sum(coefficient * (value // multiple)
                   for multiple, coefficient in coefficients.items())

    low, high = 1, upper
    while low < high:
        middle = (low + high) // 2
        if count_at_most(middle) >= k:
            high = middle
        else:
            low = middle + 1
    return low"}
